        From 3e600b874d4424e01fe3d803a993f4982f8f33df Mon Sep 17 00:00:00 2001
From: Arkadiusz Bokowy <arkadiusz.bokowy@gmail.com>
Date: Fri, 16 Feb 2018 22:01:17 +0100
Subject: [PATCH] Drain optimization - use timeout only when needed

This commit also fixes a bug introduced in the 99d9d72. Since then it
was impossible to exit (cleanly and without breaking bluealsa server)
SCO thread with a player which uses snd_pcm_drain() call.
---
 src/io.c        | 45 +++++++++++++++++++++++++++++++++------------
 src/transport.c |  1 +
 2 files changed, 34 insertions(+), 12 deletions(-)

diff --git a/src/io.c b/src/io.c
index 6900865..a9f749c 100644
--- a/src/io.c
+++ b/src/io.c
@@ -355,6 +355,7 @@ void *io_thread_a2dp_source_sbc(void *arg) {
 	int16_t *in_buffer_tail = in_buffer;
 	size_t in_samples = in_buffer_size / sizeof(int16_t);

+	int poll_timeout = -1;
 	struct asrsync asrs = { .frames = 0 };
 	struct pollfd pfds[] = {
 		{ t->event_fd, POLLIN, 0 },
@@ -371,10 +372,10 @@ void *io_thread_a2dp_source_sbc(void *arg) {
 		/* add PCM socket to the poll if transport is active */
 		pfds[1].fd = t->state == TRANSPORT_ACTIVE ? t->a2dp.pcm.fd : -1;

-		switch (poll(pfds, sizeof(pfds) / sizeof(*pfds), 100)) {
+		switch (poll(pfds, sizeof(pfds) / sizeof(*pfds), poll_timeout)) {
 		case 0:
-			if (t->a2dp.pcm.sync)
-				pthread_cond_signal(&t->a2dp.pcm.drained);
+			pthread_cond_signal(&t->a2dp.pcm.drained);
+			poll_timeout = -1;
 			continue;
 		case -1:
 			error("Transport poll error: %s", strerror(errno));
@@ -386,6 +387,8 @@ void *io_thread_a2dp_source_sbc(void *arg) {
 			eventfd_t event;
 			eventfd_read(pfds[0].fd, &event);
 			asrs.frames = 0;
+			if (t->a2dp.pcm.sync)
+				poll_timeout = 100;
 			continue;
 		}

@@ -795,6 +798,7 @@ void *io_thread_a2dp_source_aac(void *arg) {
 	size_t in_samples = in_buffer_size / in_buffer_element_size;
 	in_buffer_tail = in_buffer;

+	int poll_timeout = -1;
 	struct asrsync asrs = { .frames = 0 };
 	struct pollfd pfds[] = {
 		{ t->event_fd, POLLIN, 0 },
@@ -811,10 +815,10 @@ void *io_thread_a2dp_source_aac(void *arg) {
 		/* add PCM socket to the poll if transport is active */
 		pfds[1].fd = t->state == TRANSPORT_ACTIVE ? t->a2dp.pcm.fd : -1;

-		switch (poll(pfds, sizeof(pfds) / sizeof(*pfds), 100)) {
+		switch (poll(pfds, sizeof(pfds) / sizeof(*pfds), poll_timeout)) {
 		case 0:
-			if (t->a2dp.pcm.sync)
-				pthread_cond_signal(&t->a2dp.pcm.drained);
+			pthread_cond_signal(&t->a2dp.pcm.drained);
+			poll_timeout = -1;
 			continue;
 		case -1:
 			error("Transport poll error: %s", strerror(errno));
@@ -826,6 +830,8 @@ void *io_thread_a2dp_source_aac(void *arg) {
 			eventfd_t event;
 			eventfd_read(pfds[0].fd, &event);
 			asrs.frames = 0;
+			if (t->a2dp.pcm.sync)
+				poll_timeout = 100;
 			continue;
 		}

@@ -978,6 +984,7 @@ void *io_thread_a2dp_source_aptx(void *arg) {
 	int16_t *in_buffer_tail = in_buffer;
 	size_t in_samples = in_buffer_size / sizeof(int16_t);

+	int poll_timeout = -1;
 	struct asrsync asrs = { .frames = 0 };
 	struct pollfd pfds[] = {
 		{ t->event_fd, POLLIN, 0 },
